#include <stddef.h>

int array_sum(const int *arr, int len, int *out) {
    if (arr == NULL || len <= 0) {
        return -1;
    }
    int total = 0;
    for (int i = 0; i < len; i++) {
        total += arr[i];
    }
    *out = total;
    return 0;
}

int array_min(const int *arr, int len, int *out) {
    if (arr == NULL || len <= 0) {
        return -1;
    }
    int m = arr[0];
    for (int i = 1; i < len; i++) {
        if (arr[i] < m) {
            m = arr[i];
        }
    }
    *out = m;
    return 0;
}

int array_max(const int *arr, int len, int *out) {
    if (arr == NULL || len <= 0) {
        return -1;
    }
    int m = arr[0];
    for (int i = 1; i < len; i++) {
        if (arr[i] > m) {
            m = arr[i];
        }
    }
    *out = m;
    return 0;
}

