#include <stdio.h>

int array_sum(const int *arr, int len, int *out);
int array_min(const int *arr, int len, int *out);
int array_max(const int *arr, int len, int *out);

int main(void) {
    int data[] = {5, 2, 9, 1, 7};
    int out;

    if (array_sum(data, 5, &out) != 0 || out != 24) {
        printf("FAIL sum: got %d\n", out);
        return 1;
    }
    if (array_min(data, 5, &out) != 0 || out != 1) {
        printf("FAIL min: got %d\n", out);
        return 1;
    }
    if (array_max(data, 5, &out) != 0 || out != 9) {
        printf("FAIL max: got %d\n", out);
        return 1;
    }

    if (array_sum(NULL, 5, &out) != -1) {
        printf("FAIL: sum should reject NULL array\n");
        return 1;
    }
    if (array_min(data, 0, &out) != -1) {
        printf("FAIL: min should reject zero length\n");
        return 1;
    }
    if (array_max(data, -1, &out) != -1) {
        printf("FAIL: max should reject negative length\n");
        return 1;
    }

    printf("PASS\n");
    return 0;
}

